```file apiwrap/client.py
import time


class Transient(Exception):
    """Network-level failure."""
    pass


class Client:
    def __init__(self, transport):
        self.transport = transport

    def call(self, method, path, body=None, timeout=1.0, attempts=3,
             idempotency_key=None, backoff=0.01):
        headers = {}
        if idempotency_key is not None:
            headers["Idempotency-Key"] = idempotency_key

        idempotent_methods = frozenset({"GET", "HEAD", "PUT", "DELETE"})
        retryable = (
            method in idempotent_methods
            or (method == "POST" and idempotency_key is not None)
        )

        last_exc = None
        for i in range(1, attempts + 1):
            if i >= 2:
                time.sleep(backoff * 2 ** (i - 1))
            try:
                status, resp_body = self.transport(method, path, body, headers)
                return (status, resp_body)
            except Transient as exc:
                last_exc = exc
                if not retryable:
                    raise
            except Exception:
                raise

        raise last_exc
