from collections import defaultdict


def build(pairs, chunk=64):
    """Generator yielding batches of postings entries.

    Each batch is a list of (term, doc_id, positions) tuples where
    positions is the list of 0-based word positions of term in doc_id.
    Groups work in chunks of *chunk* documents; the last batch may be shorter.
    At most one chunk of raw text is held in memory at a time.
    """
    current_chunk = []

    for doc_id, text in pairs:
        current_chunk.append((doc_id, text))
        if len(current_chunk) >= chunk:
            yield _process_chunk(current_chunk)
            current_chunk = []

    if current_chunk:
        yield _process_chunk(current_chunk)


def _process_chunk(chunk):
    """Turn a list of (doc_id, text) into a list of postings entries."""
    batch = []
    for doc_id, text in chunk:
        tokens = text.split()
        term_positions = defaultdict(list)
        for pos, token in enumerate(tokens):
            term_positions[token].append(pos)
        for term, positions in term_positions.items():
            batch.append((term, doc_id, positions))
    return batch


def merge(base, extra):
    """Merge postings entries *extra* into *base* in place.

    base:  dict[str, dict[str, list[int]]]   term -> {doc_id: [positions]}
    extra: list of (term, doc_id, positions)

    Unioning and sorting every position list.  Returns *base*.
    """
    for term, doc_id, positions in extra:
        if term not in base:
            base[term] = {}
        if doc_id not in base[term]:
            base[term][doc_id] = []
        base[term][doc_id].extend(positions)
        base[term][doc_id] = sorted(set(base[term][doc_id]))
    return base


class Index:
    """In-memory inverted index."""

    def __init__(self):
        self._index = {}  # term -> {doc_id: [positions]}
        self._doc_count = 0

    @property
    def doc_count(self):
        return self._doc_count

    def terms(self):
        return list(self._index.keys())

    def rebuild(self, pairs):
        """Set the index to a fresh build (not a merge).

        Returns the total number of postings (sum of every position-list length).
        """
        self._index = {}
        self._doc_count = 0

        for batch in build(pairs):
            merge(self._index, batch)

        total = 0
        docs = set()
        for term in self._index:
            for doc_id, positions in self._index[term].items():
                total += len(positions)
                docs.add(doc_id)
        self._doc_count = len(docs)
        return total

    def lookup(self, term):
        """Return a sorted list of doc ids containing *term*."""
        if term not in self._index:
