"""Exact-cent money type with allocation support."""

from decimal import Decimal, ROUND_HALF_UP, ROUND_FLOOR


class CurrencyMismatch(Exception):
    """Raised when arithmetic is attempted between different currencies."""


class Money:
    """An immutable monetary amount stored as an exact integer number of cents."""

    __slots__ = ("_cents", "_currency")

    # ------------------------------------------------------------------ #
    # Construction
    # ------------------------------------------------------------------ #

    def __init__(self, amount, currency="USD"):
        self._currency = currency
        self._cents = self._to_cents(amount)

    @classmethod
    def _from_cents(cls, cents, currency):
        obj = cls.__new__(cls)
        obj._cents = int(cents)
        obj._currency = currency
        return obj

    @staticmethod
    def _to_cents(amount):
        if isinstance(amount, int):
            return amount * 100
        if isinstance(amount, float):
            d = Decimal(str(amount))
        elif isinstance(amount, Decimal):
            d = amount
        elif isinstance(amount, str):
            d = Decimal(amount)
        else:
            d = Decimal(str(amount))
        return int((d * 100).to_integral_value(rounding=ROUND_HALF_UP))

    # ------------------------------------------------------------------ #
    # Properties
    # ------------------------------------------------------------------ #

    @property
    def cents(self):
        return self._cents

    @property
    def currency(self):
        return self._currency

    # ------------------------------------------------------------------ #
    # Arithmetic
    # ------------------------------------------------------------------ #

    def _check_currency(self, other):
        if self._currency != other._currency:
            raise CurrencyMismatch(
                f"Cannot combine {self._currency} with {other._currency}"
            )

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return Money._from_cents(self._cents + other._cents, self._currency)

    def __sub__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return Money._from_cents(self._cents - other._cents, self._currency)

    def __mul__(self, other):
        if isinstance(other, int):
            new_cents = self._cents * other
        elif isinstance(other, Decimal):
            new_cents = int(
                (Decimal(self._cents) * other).to_integral_value(
                    rounding=ROUND_HALF_UP
                )
            )
        else:
            return NotImplemented
        return Money._from_cents(new_cents, self._currency)

    def __rmul__(self, other):
        return self.__mul__(other)

    def __neg__(self):
        return Money._from_cents(-self._cents, self._currency)

    # ------------------------------------------------------------------ #
    # Comparison / hashing
    # ------------------------------------------------------------------ #

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return self._cents == other._cents and self._currency == other._currency

    def __lt__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._check_currency(other)
        return self._cents < other._cents

    def __hash__(self):
        return hash((self._cents, self._currency))

    # ------------------------------------------------------------------ #
    # Allocation
    # ------------------------------------------------------------------ #

    def allocate(self, pairs):
        """Split this amount across *pairs* of (key, weight).

        The returned dict maps each key to a Money whose cents sum **exactly**
        to ``self.cents``.  Remainder cents are assigned to the largest-weight
        entries first; ties are broken by earlier position in *pairs*.
        """
        pairs = list(pairs)
        if not pairs:
            return {}

        for key, weight in pairs:
            if weight <= 0:
                raise ValueError(
                    f"Weight for {key!r} must be positive, got {weight}"
                )

        total_cents = self._cents

        if total_cents == 0:
            return {
                key: Money._from_cents(0, self._currency)
                for key, _ in pairs
            }

        total_weight = sum(Decimal(w) for _, w in pairs)

        bases = []
        for _key, weight in pairs:
            exact = Decimal(total_cents) * Decimal(weight) / total_weight
            bases.append(int(exact.to_integral_value(rounding=ROUND_FLOOR)))

        remainder = total_cents - sum(bases)

        # Order indices by weight descending, then by original position.
        order = sorted(
            range(len(pairs)),
            key=lambda i: (-Decimal(pairs[i][1]), i),
        )

        result_cents = list(bases)
        for j in range(remainder):
            result_cents[order[j]] += 1

        return {
            key: Money._from_cents(cents, self._currency)
            for (key, _), cents in zip(pairs, result_cents)
        }

    # ------------------------------------------------------------------ #
    # Formatting / repr
    # ------------------------------------------------------------------ #

    def format(self):
        if self._cents < 0:
            sign = "-"
            abs_cents = -self._cents
        else:
            sign = ""
            abs_cents = self._cents
        dollars = abs_cents // 100
        cents = abs_cents % 100
        return f"{sign}${dollars}.{cents:02d}"

    def __repr__(self):
        return f"Money({self._cents}, {self._currency!r})"

    def __str__(self):
        return self.format()
