import copy


class InvalidEvent(Exception):
    pass


class Aggregate:
    _known_events: set = set()

    def __init__(self):
        self._state = {}
        self._version = 0
        self._pending = []
        self._applied_seqs = set()

    @property
    def version(self):
        return self._version

    @property
    def pending(self):
        return list(self._pending)

    def handle(self, command):
        events = self._produce_events(command)
        self._pending.extend(events)
        return list(events)

    def apply(self, event):
        name = event.get("name")
        if name is None or name not in self._known_events:
            raise InvalidEvent(f"Unknown event name: {name!r}")

        seq = event.get("seq")
        if seq is not None and seq in self._applied_seqs:
            raise InvalidEvent(f"Duplicate seq: {seq!r}")

        if not self._guard(event):
            raise InvalidEvent(f"Guard rejected event: {name!r}")

        self._state = self._reduce(self._state, event)
        self._version += 1
