import threading
from itertools import islice


class Store:
    def __init__(self):
        self._lock = threading.Lock()
        self._data = {}
        self._offered = set()
        self._contended = set()

    def put_if_absent(self, key, value):
        with self._lock:
            if key in self._offered:
                self._contended.add(key)
            self._offered.add(key)
            if key in self._data:
                return False
            self._data[key] = value
            return True

    def get(self, key):
        with self._lock:
            return self._data.get(key)

    def process(self, items, chunk=500):
        stored = 0
        duplicates = 0
        it = iter(items)
        while True:
            batch = list(islice(it, chunk))
            if not batch:
                break
            for key, value in batch:
                if self.put_if_absent(key, value):
                    stored += 1
                else:
                    duplicates += 1
        return {"stored": stored, "duplicates": duplicates}

    def stats(self):
        with self._lock:
            return {"keys": len(self._data), "contended": len(self._contended)}

    def __len__(self):
        with self._lock:
            return len(self._data)
