import csv
import io
import os


class Reader:
    """Parse CSV text or file-like sources with correct quoting and dialects."""

    DIALECTS = {
        "excel": ",",
        "excel-tab": "\t",
        "pipe": "|",
    }

    def __init__(self, source, dialect="excel", delimiter=None):
        if delimiter is not None:
            self._delimiter = delimiter
        elif dialect in self.DIALECTS:
            self._delimiter = self.DIALECTS[dialect]
        else:
            raise ValueError(f"Unknown dialect: {dialect!r}")

        if hasattr(source, "read"):
            text = source.read()
        else:
            text = source

        reader = csv.reader(
            io.StringIO(text),
            delimiter=self._delimiter,
            quotechar='"',
            doublequote=True,
        )
        self._rows_raw = list(reader)

        if self._rows_raw:
            self._fieldnames = [f.strip() for f in self._rows_raw[0]]
        else:
            self._fieldnames = []

    @property
    def fieldnames(self):
        return self._fieldnames

    def rows(self):
        """Yield dicts of stripped keys/values, skipping fully-blank rows."""
        for row in self._rows_raw[1:]:
            if all(not cell.strip() for cell in row):
                continue
            d = {}
            for i, name in enumerate(self._fieldnames):
                if i < len(row):
                    d[name] = row[i].strip()
                else:
                    d[name] = None
            yield d

    @classmethod
    def read(cls, path_or_text, dialect="excel", delimiter=None):
        """Open *path_or_text* as a file if it exists, otherwise treat it as CSV text."""
        if os.path.isfile(path_or_text):
            with open(path_or_text, "r", newline="") as fh:
                return cls(fh, dialect=dialect, delimiter=delimiter)
        return cls(path_or_text, dialect=dialect, delimiter=delimiter)

    @classmethod
    def write(cls, path, fieldnames, rows, dialect="excel", delimiter=None):
        """Write *rows* (iterable of dicts) to *path* with minimal quoting."""
        if delimiter is not None:
            delim = delimiter
        elif dialect in cls.DIALECTS:
            delim = cls.DIALECTS[dialect]
        else:
            raise ValueError(f"Unknown dialect: {dialect!r}")

        with open(path, "w", newline="") as fh:
            writer = csv.writer(
                fh,
                delimiter=delim,
                quotechar='"',
                doublequote=True,
                quoting=csv.QUOTE_MINIMAL,
            )
            writer.writerow(fieldnames)
            for row in rows:
                writer.writerow([row.get(name, "") for name in fieldnames])
