import heapq

from mig.errors import MigrationError


def plan(migrations):
    """Topological sort of migration names. Ties broken alphabetically.

    Raises MigrationError on a missing dependency or a dependency cycle.
    """
    by_name = {m["name"]: m for m in migrations}

    for m in migrations:
        for dep in m.get("deps", []):
            if dep not in by_name:
                raise MigrationError(
                    f"Migration '{m['name']}' depends on unknown migration '{dep}'"
                )

    in_degree = {m["name"]: 0 for m in migrations}
    dependents = {m["name"]: [] for m in migrations}

    for m in migrations:
        for dep in m.get("deps", []):
            in_degree[m["name"]] += 1
            dependents[dep].append(m["name"])

    heap = [name for name, deg in in_degree.items() if deg == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        name = heapq.heappop(heap)
        result.append(name)
        for child in dependents[name]:
            in_degree[child] -= 1
            if in_degree[child] == 0:
                heapq.heappush(heap, child)

    if len(result) != len(migrations):
        raise MigrationError("Dependency cycle detected")

    return result


def applied(db):
    """Return the set of migration names already recorded in *db*."""
    return set(db.applied_migrations)


def migrate(conn, migrations, db, dry_run=False):
    """Apply every planned migration not yet recorded.

    Returns the list of names applied (in order).  On failure the
    migrations applied during *this* call are rolled back (down in
    reverse order) and the original exception propagates.
    """
    order = plan(migrations)
    already = applied(db)
    to_apply = [name for name in order if name not in already]

    if dry_run:
        return to_apply

    by_name = {m["name"]: m for m in migrations}
    applied_this_call = []

    try:
        for name in to_apply:
            m = by_name[name]
            m["up"](conn)
            db.record(name)
            applied_this_call.append(name)
    except Exception:
        for name in reversed(applied_this_call):
            by_name[name]["down"](conn)
        raise

    return applied_this_call


def rollback_last(conn, migrations, db):
    """Undo the most-recently recorded migration and remove its record."""
    if not db.applied_migrations:
        return

    name = db.applied_migrations[-1]
    by_name = {m["name"]: m for m in migrations}
    m = by_name[name]
    m["down"](conn)
    db.applied_migrations.pop()
