class Windowed:
    _peak_memory = 0

    def __init__(self, source, size, fn, key=None):
        if size <= 0:
            raise ValueError("size must be positive")
        self.source = source
        self.size = size
        self.fn = fn
        self.key = key

    def __iter__(self):
        buffers = {}
        for item in self.source:
            if self.key is None:
                k = None
                v = item
            else:
                k, v = item

            buf = buffers.setdefault(k, [])
            buf.append(v)

            if len(buf) > Windowed._peak_memory:
                Windowed._peak_memory = len(buf)

            if len(buf) == self.size:
                yield (k, self.fn(buf))
                buffers[k] = []

    @classmethod
    def peak_memory(cls):
        return cls._peak_memory


def summarise(source, size, fn, key=None):
    return [result for _, result in Windowed(source, size, fn, key)]
