class ExprError(Exception):
    """Raised on any syntax error in an expression."""


def tokenize(text):
    """Tokenize *text* into a list of (type, value) tuples."""
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch in ' \t\n\r':
            i += 1
            continue
        if ch.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            tokens.append(('NUM', int(text[i:j])))
            i = j
        elif ch == '(':
            tokens.append(('LPAREN', '('))
            i += 1
        elif ch == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
        elif ch == '*' and i + 1 < n and text[i + 1] == '*':
            tokens.append(('OP', '**'))
            i += 2
        elif ch == '*':
            tokens.append(('OP', '*'))
            i += 1
        elif ch == '/' and i + 1 < n and text[i + 1] == '/':
            tokens.append(('OP', '//'))
            i += 2
        elif ch == '/':
            tokens.append(('OP', '/'))
            i += 1
        elif ch == '+':
            tokens.append(('OP', '+'))
            i += 1
        elif ch == '-':
            tokens.append(('OP', '-'))
            i += 1
        else:
            raise ExprError(f"unexpected character {ch!r} at position {i}")
    return tokens


def parse(text):
    """Parse and evaluate *text*, returning an int or float."""
    if not text or not text.strip():
        raise ExprError("empty expression")

    tokens = tokenize(text)
    if not tokens:
        raise ExprError("empty expression")

    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def consume():
        tok = peek()
        if tok is None:
            raise ExprError("unexpected end of expression")
        pos[0] += 1
        return tok

    def parse_expr():
        val = parse_term()
        while peek() and peek()[0] == 'OP' and peek()[1] in ('+', '-'):
            op = consume()[1]
            rhs = parse_term()
            if op == '+':
                val = val + rhs
            else:
                val = val - rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek() and peek()[0] == 'OP' and peek()[1] in ('*', '/', '//'):
            op = consume()[1]
            rhs = parse_factor()
            if op == '*':
                val = val * rhs
            elif op == '/':
                val = val / rhs
            else:
                val = val // rhs
        return val

    def parse_factor():
        tok = peek()
        if tok and tok[0] == 'OP' and tok[1] in ('+', '-'):
            op = consume()[1]
            val = parse_factor()
            if op == '-':
                return -val
            return val
        return parse_power()

    def parse_power():
        val = parse_atom()
        if peek() and peek()[0] == 'OP' and peek()[1] == '**':
            consume()
            rhs = parse_factor()
            val = val ** rhs
        return val

    def parse_atom():
        tok = peek()
        if tok is None:
            raise ExprError("unexpected end of expression")
        if tok[0] == 'NUM':
            consume()
            return tok[1]
        if tok[0] == 'LPAREN':
            consume()
            val = parse_expr()
            if peek() is None or peek()[0] != 'RPAREN':
                raise ExprError("unbalanced parentheses")
            consume()
            return val
        raise ExprError(f"unexpected token {tok[1]!r}")

    result = parse_expr()
    if pos[0] != len(tokens):
        raise ExprError(f"unexpected trailing token {tokens[pos[0]][1]!r}")
    return result
