        for ch in word:
            if ch not in node.children:
                node.children[ch] = _TrieNode()
            node = node.children[ch]
        if node.weight is None:
            self._size += 1
        node.weight = weight

    def remove(self, word):
        word = word.lower()
        path = []
        node = self._root
        for ch in word:
            if ch not in node.children:
                return
            path.append((node, ch))
            node = node.children[ch]
        if node.weight is None:
            return
        node.weight = None
        self._size -= 1
        for parent, ch in reversed(path):
            child = parent.children[ch]
            if not child.children and child.weight is None:
                del parent.children[ch]
            else:
                break

    def complete(self, prefix, limit=10):
        prefix = prefix.lower()
        node = self._root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        results = []
        self._collect(node, prefix, results)
        results.sort(key=lambda w: (-w[1], w[0]))
        if limit is None or limit == 0:
            return [w[0] for w in results]
        return [w[0] for w in results[:limit]]

