from dataclasses import dataclass
from typing import Any, Callable, Iterable, List, Optional, Tuple


@dataclass
class BatchStats:
    processed: int
    failed: int


def chunked(source: Iterable, size: int):
    if size <= 0:
        raise ValueError("size must be a positive integer")
    chunk: List[Any] = []
    for item in source:
        chunk.append(item)
        if len(chunk) == size:
            yield chunk
            chunk = []
    if chunk:
        yield chunk


def run_batches(
    source: Iterable,
    fn: Callable,
    size: int,
    on_error: Optional[Callable] = None,
) -> Tuple[List, BatchStats]:
    results: List[Any] = []
    processed = 0
    failed = 0
    for chunk in chunked(source, size):
        processed += 1
        try:
            results.append(fn(chunk))
        except Exception as exc:
            results.append(None)
            failed += 1
            if on_error is not None:
                on_error(chunk, exc)
    return results, BatchStats(processed, failed)
