import pathlib


class Worker:
    def __init__(self, model, shards, out_dir, checkpoint_every=10):
        self.model = model
        self.shards = shards
        self.out_dir = pathlib.Path(out_dir)
        self.checkpoint_every = checkpoint_every
        self.total_inferred = 0
        self._skipped_this_call = 0

        # Model is loaded ONCE – assert the load counter stays at 1.
        if hasattr(model, "load_count"):
            assert model.load_count == 1, "Model must be loaded exactly once"

        self.out_dir.mkdir(parents=True, exist_ok=True)

    # ── path helpers ──────────────────────────────────────────────
    def _done_path(self):
        return self.out_dir / "done.txt"

    def _failed_path(self):
        return self.out_dir / "failed.txt"

    def _output_path(self, shard_id):
        return self.out_dir / f"{shard_id}.txt"

    # ── I/O helpers ───────────────────────────────────────────────
    def _read_done(self):
        p = self._done_path()
        if p.exists():
            return set(line.strip() for line in p.read_text().splitlines() if line.strip())
        return set()

    def _read_failed(self):
        p = self._failed_path()
        if p.exists():
            return set(line.strip() for line in p.read_text().splitlines() if line.strip())
        return set()

    def _write_done(self, done_ids):
        with open(self._done_path(), "w") as f:
            for sid in done_ids:
                f.write(f"{sid}\n")

    def _append_failed(self, shard_id):
        with open(self._failed_path(), "a") as f:
            f.write(f"{shard_id}\n")

    def _remove_failed(self, shard_id):
        p = self._failed_path()
        if not p.exists():
            return
        lines = [l for l in p.read_text().splitlines() if l.strip() != str(shard_id)]
        p.write_text("\n".join(lines) + "\n" if lines else "")

    # ── main run ──────────────────────────────────────────────────
    def run(self):
        done_ids = self._read_done()
        self._skipped_this_call = 0
        pending = []

        for shard in self.shards:
            shard_id = shard.id
            output_file = self._output_path(shard_id)

            # Resume: already recorded AND output file exists → skip.
            if shard_id in done_ids and output_file.exists():
                self._skipped_this_call += 1
                continue

            # Infer (count every call, even failures).
            try:
                result = self.model.infer(shard.text)
                self.total_inferred += 1
            except Exception:
                self.total_inferred += 1
                self._append_failed(shard_id)
                continue

            # Success: write output, buffer the id.
            output_file.write_text(result)
            pending.append(shard_id)
            done_ids.add(shard_id)

            # Checkpoint every N completed shards.
            if len(pending) >= self.checkpoint_every:
                self._write_done(done_ids)
                pending = []

        # Always flush at the end.
        self._write_done(done_ids)

    # ── stats ─────────────────────────────────────────────────────
    def stats(self):
        done_ids = self._read_done()
        failed_ids = self._read_failed()
        shard_ids = {s.id for s in self.shards}

        return {
            "total": len(self.shards),
            "done": len(shard_ids & done_ids),
            "skipped": self._skipped_this_call,
            "failed": len(failed_ids),
        }

    # ── retry failed ──────────────────────────────────────────────
    def retry_failed(self):
        failed_ids = self._read_failed()
        if not failed_ids:
            return 0

        shard_map = {s.id: s for s in self.shards}
        succeeded = 0

        for shard_id in list(failed_ids):
            shard = shard_map.get(shard_id)
            if shard is None:
                continue

            try:
                result = self.model.infer(shard.text)
                self.total_inferred += 1
            except Exception:
                self.total_inferred += 1
                # Still failed – stays in failed.txt.
                continue

            # Success: write output, record in done, remove from failed.
            self._output_path(shard_id).write_text(result)
            self._append_done_id(shard_id)
            self._remove_failed(shard_id)
            succeeded += 1

        return succeeded

    def _append_done_id(self, shard_id):
        with open(self._done_path(), "a") as f:
            f.write(f"{shard_id}\n")
