"""cfgx.merge – layered config merging with list strategies and DROP sentinel."""

from __future__ import annotations

from copy import deepcopy
from types import MappingProxyType
from typing import Any, Hashable


# ─── sentinel ────────────────────────────────────────────────────────────────

class _DropType:
    """Singleton sentinel: a key whose value is DROP is removed from the result."""

    _instance: _DropType | None = None

    def __new__(cls) -> _DropType:
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __repr__(self) -> str:
        return "DROP"

    def __bool__(self) -> bool:
        return False


DROP = _DropType()


# ─── helpers ─────────────────────────────────────────────────────────────────

def _deep_delete(cfg: dict, dotted: str) -> None:
    """Remove a nested key identified by a dotted path. No-op if path missing."""
    keys = dotted.split(".")
    current: Any = cfg
    for key in keys[:-1]:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            return
    if isinstance(current, dict):
        current.pop(keys[-1], None)


def _merge_layer(base: dict, layer: dict, lists: str) -> dict:
    """Merge *layer* into *base* (both already deep-copied). Mutates *base*."""
    for key, value in layer.items():
        # ── dotted-path DROP ──────────────────────────────────────────────
        if isinstance(key, str) and "." in key:
            if value is DROP:
                _deep_delete(base, key)
            else:
                # dotted key with non-DROP value: treat as literal key
                base[key] = deepcopy(value)
            continue

        # ── plain DROP ────────────────────────────────────────────────────
        if value is DROP:
            base.pop(key, None)
            continue

        # ── dict + dict → recurse ─────────────────────────────────────────
        if isinstance(value, dict) and isinstance(base.get(key), dict):
            base[key] = _merge_layer(base[key], value, lists)
            continue

        # ── list + list → strategy ────────────────────────────────────────
        if isinstance(value, list) and isinstance(base.get(key), list):
            if lists == "replace":
                base[key] = deepcopy(value)
            elif lists == "concat":
                base[key] = base[key] + deepcopy(value)
            elif lists == "unique":
                combined = base[key] + deepcopy(value)
                seen: list = []
                for item in combined:
                    if item not in seen:
                        seen.append(item)
                base[key] = seen
            else:
                raise ValueError(f"Invalid lists strategy: {lists!r}")
            continue

        # ── everything else → wholesale replace ───────────────────────────
        base[key] = deepcopy(value)

    return base


# ─── public API ──────────────────────────────────────────────────────────────

def merge(base: dict, *layers: dict, lists: str = "replace") -> dict:
    """Merge *base* with successive *layers*.

    Parameters
    ----------
    base : dict
        Starting configuration. Never mutated.
    *layers : dict
        Successive override layers. Never mutated.
    lists : {'replace', 'concat', 'unique'}
        How to combine list values that appear in both sides.

    Returns
    -------
    dict
        A new, fully merged configuration. DROP never appears in the output.
    """
    result = deepcopy(base)
    for layer in layers:
        result = _merge_layer(result, deepcopy(layer), lists)
    return result


def deep_get(cfg: Any, path: str, default: Any = None) -> Any:
    """Read a dotted path from a nested dict. Returns *default* if missing."""
    keys = path.split(".")
    current: Any = cfg
    for key in keys:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            return default
    return current


def deep_set(cfg: dict, path: str, value: Any) -> dict:
    """Return a NEW config with *path* set to *value*, creating intermediates."""
    keys = path.split(".")
    result = deepcopy(cfg)
    current: Any = result
    for key in keys[:-1]:
        if not isinstance(current, dict):
            raise TypeError(f"Cannot set path {path!r}: {key!r} is not a dict")
        if key not in current or not isinstance(current[key], dict):
            current[key] = {}
