class UnknownState(Exception):
    pass


class GuardFailed(Exception):
    pass


class NotParallel(Exception):
    pass


class Machine:
    def __init__(self, initial, states, on_transition=None):
        self._state = initial
        self._states = states
        self._on_transition = on_transition
        self._history = [initial]
        self._active_region = None
        self._active_branch = None
        self._region_progress = {}

    @property
    def history(self):
        return list(self._history)

    def go(self, target, **ctx):
        if target not in self._states:
            raise UnknownState(target)

        src = self._state
        transition = self._find_transition(src, target)
        if transition is None:
            raise UnknownState(target)

        guard = transition.get("guard")
        if guard is not None:
            if not guard(**ctx):
                raise GuardFailed()

        saved_state = self._state
        saved_history_len = len(self._history)
        saved_active_region = self._active_region
        saved_active_branch = self._active_branch
        saved_region_progress = {k: dict(v) for k, v in self._region_progress.items()}

        self._state = target
        self._history.append(target)

        target_def = self._states[target]

        if isinstance(target_def, dict) and "parallel" in target_def:
            self._active_region = target
            self._active_branch = None
            self._region_progress[target] = {b: None for b in target_def["parallel"]}
        elif (
            self._active_region is not None
            and target in self._states[self._active_region].get("parallel", [])
        ):
            self._active_branch = target
            self._region_progress[self._active_region][target] = target
        elif self._active_region is not None and self._active_branch is not None:
            self._region_progress[self._active_region][self._active_branch] = target
            if isinstance(target_def, list) and len(target_def) == 0:
                self._region_progress[self._active_region][self._active_branch] = "done"
                if all(
                    v == "done"
                    for v in self._region_progress[self._active_region].values()
                ):
                    self._active_region = None
                    self._active_branch = None

        action = transition.get("action")
        result = target
        if action is not None:
            try:
                result = action(**ctx)
            except Exception:
                self._state = saved_state
                self._history = self._history[:saved_history_len]
                self._active_region = saved_active_region
                self._active_branch = saved_active_branch
                self._region_progress = saved_region_progress
                raise

        if self._on_transition is not None:
            self._on_transition(src, target)

        return result

    def join(self, name):
        if name not in self._states:
            raise NotParallel(name)
        state_def = self._states[name]
        if not isinstance(state_def, dict) or "parallel" not in state_def:
            raise NotParallel(name)

        progress = self._region_progress.get(name)
        if progress is None:
            return False

        return all(v == "done" for v in progress.values())

    def _find_transition(self, src, target):
        src_def = self._states.get(src)
        if src_def is None:
            return None

        if isinstance(src_def, dict) and "parallel" in src_def:
            if target in src_def["parallel"]:
                return {"to": target}
        elif isinstance(src_def, list):
            for t in src_def:
                if t["to"] == target:
                    return t

        if self._active_region is not None:
            region_def = self._states[self._active_region]
            if target in region_def.get("parallel", []):
                return {"to": target}

        return None
